import{_ as t,C as i,o as r,c as s,aj as a,E as n}from"./framework.js";const g=JSON.parse('{"title":"Domains | Manual | Admin CMS","description":"Every Kooboo account includes a free domain for testing before launch. For a live site, buy a proper domain and bind it to the site.","frontmatter":{"title":"Domains | Manual | Admin CMS","description":"Every Kooboo account includes a free domain for testing before launch. For a live site, buy a proper domain and bind it to the site.","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/manual/domains.html"}]]},"headers":[],"relativePath":"cms/manual/domains.md","filePath":"en/cms/manual/domains.md","lastUpdated":1793060327000}'),d={name:"cms/manual/domains.md"};function h(l,e,c,m,u,p){const o=i("DocImage");return r(),s("div",null,[e[0]||(e[0]=a('<h1 id="domains" tabindex="-1">Domains <a class="header-anchor" href="#domains" aria-label="Permalink to &quot;Domains&quot;">​</a></h1><p>Every Kooboo account includes a free domain for testing before launch. For a live site, buy a proper domain and bind it to the site.</p><h2 id="where-to-buy-china-vs-overseas" tabindex="-1">Where to buy (China vs overseas) <a class="header-anchor" href="#where-to-buy-china-vs-overseas" aria-label="Permalink to &quot;Where to buy (China vs overseas)&quot;">​</a></h2><ul><li><strong>Sites in mainland China</strong> need ICP filing. Kooboo does not support filing, so buy the domain on <strong>Alibaba Cloud (Aliyun)</strong>, set DNS, then add it in Kooboo.</li><li><strong>Overseas sites</strong> need no filing; you can buy the domain in Kooboo.</li></ul><h2 id="buy-a-domain-in-kooboo" tabindex="-1">Buy a domain in Kooboo <a class="header-anchor" href="#buy-a-domain-in-kooboo" aria-label="Permalink to &quot;Buy a domain in Kooboo&quot;">​</a></h2><p>Open <strong>Domains</strong> in the console, then <strong>Buy domain</strong> (or the other purchase entry on that page).</p><ol><li>Search for the domain. If it is available, click <strong>Register</strong>.</li><li>Choose the term. Contact details are optional; leave them on automatic if empty.</li><li>Click <strong>OK</strong> to open the payment page.</li></ol><p>This guide stops at the payment page; complete payment in the admin yourself. Purchased domains appear in the domain list and can then be bound to a site.</p>',8)),n(o,{src:"/cms/manual/domains/list.jpg",alt:"On the domain list, click Buy domain to start purchasing"}),n(o,{src:"/cms/manual/domains/buy.jpg",alt:"Search for a domain and select TLDs, then click Search"}),e[1]||(e[1]=a('<h2 id="add-a-domain-bought-elsewhere" tabindex="-1">Add a domain bought elsewhere <a class="header-anchor" href="#add-a-domain-bought-elsewhere" aria-label="Permalink to &quot;Add a domain bought elsewhere&quot;">​</a></h2><ol><li>In your registrar’s DNS panel (for example Aliyun), add two <strong>CNAME</strong> records: <ul><li>Host <code>@</code> for the apex (for example <code>example.com</code>)</li><li>Host <code>*</code> for subdomains (for example <code>www.example.com</code>)</li></ul></li><li>Set the record value to your Kooboo server domain. You can see it in the console <strong>Domains → New</strong> dialog.</li><li>If the registrar (for example GoDaddy) cannot CNAME the apex, use their domain forwarding to send the apex to something like <code>www.example.com</code>.</li><li>In Kooboo: <strong>Console → Domains → New domain</strong>, enter the domain that already has those CNAMEs. You can then bind it to a site.</li></ol><h2 id="bind-or-change-the-site-domain" tabindex="-1">Bind or change the site domain <a class="header-anchor" href="#bind-or-change-the-site-domain" aria-label="Permalink to &quot;Bind or change the site domain&quot;">​</a></h2><p>Open <strong>Site settings → Domains</strong>.</p><ul><li>Remove an old domain: check it, then delete. Right after a CNAME change, wait for the TTL before testing.</li><li>Bind a new domain: click <strong>New binding</strong> and choose the production domain. Switching to that domain is effectively going live.</li><li>Visitors then use the new domain; the site list also shows the current domain.</li></ul>',5)),n(o,{src:"/cms/manual/domains/bind.jpg",alt:"In New binding, enter the domain, pick a site, then create"}),e[2]||(e[2]=a('<h2 id="site-unreachable-after-dns-changes" tabindex="-1">Site unreachable after DNS changes <a class="header-anchor" href="#site-unreachable-after-dns-changes" aria-label="Permalink to &quot;Site unreachable after DNS changes&quot;">​</a></h2><h3 id="_404-not-found" tabindex="-1">404 (Not Found) <a class="header-anchor" href="#_404-not-found" aria-label="Permalink to &quot;404 (Not Found)&quot;">​</a></h3><p>Likely cause: the domain does not resolve to the Kooboo server.</p><p>Check: open DevTools (F12). For any request, see whether <strong>Remote Address</strong> is a Kooboo server IP, or whether the <strong>Server</strong> response header shows a Kooboo version (either is enough; Server is easier). If neither matches, point the domain at Kooboo as in the previous section, then retry.</p><h3 id="err-connection-reset" tabindex="-1">ERR_CONNECTION_RESET <a class="header-anchor" href="#err-connection-reset" aria-label="Permalink to &quot;ERR_CONNECTION_RESET&quot;">​</a></h3><p>Likely cause: a network issue; or, right after a DNS change, the TTL has not expired yet.</p><p>Check: try another network. If you just changed DNS, wait for the TTL, then retry.</p><h3 id="err-too-many-redirects" tabindex="-1">ERR_TOO_MANY_REDIRECTS <a class="header-anchor" href="#err-too-many-redirects" aria-label="Permalink to &quot;ERR_TOO_MANY_REDIRECTS&quot;">​</a></h3><p>Likely cause: a bad CNAME creating a redirect loop.</p><p>Check: confirm the CNAME points at the Kooboo server.</p><h2 id="renew-a-domain" tabindex="-1">Renew a domain <a class="header-anchor" href="#renew-a-domain" aria-label="Permalink to &quot;Renew a domain&quot;">​</a></h2><p>When a domain is near expiry, open the renew page, choose the term, and complete renewal.</p>',12))])}const f=t(d,[["render",h]]);export{g as __pageData,f as default};
